/// Where a finding lands. Only the rule engine in SweepCore assigns one.
public enum Bucket: String, Sendable, Codable, CaseIterable {
    /// Regenerated by its owner; deleted directly, ticked by default.
    case rebuilds
    /// Probably not needed; moved to Trash after the user ticks it.
    case review
    /// The user's own files; shown with "Show in Finder" only.
    case yours
    /// Never offered to the user.
    case dontTouch

    public var isPreselected: Bool { self == .rebuilds }
    public var isShown: Bool { self != .dontTouch }
}
